mapper.select:
select
ta.* ,tu.id as owner_id, tu.name as owner_name
from t_activity as ta left join t_user as tu on ta.owner_id = tu.id

  ${param1.filterSql}

    and ta.owner_id = #{param2.ownerId,jdbcType=INTEGER}


      and ta.`name` like concat('%',#{param2.activityName,jdbcType=VARCHAR},'%')


      and ta.start_time >= #{param2.beginTime,jdbcType=TIMESTAMP}


      and ta.end_time <= #{param2.endTime,jdbcType=TIMESTAMP}


      and ta.cost between #{param2.costBegin,jdbcType=DECIMAL} and
    #{param2.costEnd,jdbcType=DECIMAL}


      and ta.create_time >= #{param2.createTime,jdbcType=TIMESTAMP}


order by ta.create_time desc
